e: 0,\n        path: '/',\n    })\n    return response\n}\n\n// ── Firestore OTP İşlemleri ──────────────────────────────────────────────────\nconst OTP_TTL_MS = 3 * 60 * 1000 // 3 dakika\nconst OTP_RATE_MS = 60 * 1000    // 60 saniye (gönderim arası minimum bekleme)\n\nimport { adminDb } from './firebaseAdmin'\n\nexport async function otpKaydet(telefon: string, kod: string): Promise<void> {\n    await adminDb.collection('otp_sessions').doc(telefon).set({\n        kod,\n        telefon,\n        olusturma: new Date(),\n        sonKullanim: new Date(Date.now() + OTP_TTL_MS),\n    })\n}\n\nexport async function otpDogrula(telefon: string, kod: string): Promise<boolean> {\n    const ref = adminDb.collection('otp_sessions').doc(telefon)\n    const doc = await ref.get()\n\n    if (!doc.exists) return false\n\n    const data = doc.data()!\n    const suruDoldu = new Date() > new Date(data.sonKullanim?.toDate?.() || data.sonKullanim)\n    if (suruDoldu) {\n        await ref.delete()\n        return false\n    }\n\n    if (data.kod !== String(kod)) return false\n\n    // Başarılı — OTP'yi sil\n    await ref.delete()\n    return true\n}\n\nexport async function otpRateKontrol(telefon: string): Promise<boolean> {\n    const doc = await adminDb.collection('otp_sessions').doc(telefon).get()\n\n    if (!doc.exists) return true // Rate limit yok, gönderilebilir\n\n    const data = doc.data()!\n    const olusturma = data.olusturma?.toDate?.() || new Date(data.olusturma)\n    return (Date.now() - olusturma.getTime()) >= OTP_RATE_MS\n}\n\nexport { COOKIE_ADI }\n","import { NextResponse } from 'next/server'\nimport { adminDb } from '@/lib/firebaseAdmin'\nimport { oturumOlustur } from '@/lib/sessionManager'\n\nexport async function POST(req: Request) {\n  try {\n    const { credential } = await req.json()\n    if (!credential) {\n      return NextResponse.json({ error: 'Credential gerekli' }, { status: 400 })\n    }\n\n    // Google tokeninfo ile doğrula (harici paket gerekmez)\n    const controller = new AbortController()\n    const timeout = setTimeout(() => controller.abort(), 5000)\n    let payload: Record<string, string>\n    try {\n      const res = await fetch(\n        `https://oauth2.googleapis.com/tokeninfo?id_token=${credential}`,\n        { signal: controller.signal }\n      )\n      clearTimeout(timeout)\n      if (!res.ok) {\n        return NextResponse.json({ error: 'Geçersiz Google token' }, { status: 401 })\n      }\n      payload = await res.json()\n    } catch {\n      clearTimeout(timeout)\n      return NextResponse.json({ error: 'Google doğrulama zaman aşımı' }, { status: 502 })\n    }\n\n    // Audience kontrolü\n    const clientId = process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID\n    if (clientId && payload.aud !== clientId) {\n      return NextResponse.json({ error: 'Token audience uyuşmuyor' }, { status: 401 })\n    }\n\n    const googleEmail = (payload.email || '').toLowerCase()\n    const googleName = payload.name || ''\n\n    if (!googleEmail) {\n      return NextResponse.json({ error: 'Email bilgisi alınamadı' }, { status: 400 })\n    }\n\n    // Firestore'da email ile ara\n    const sorgu = await adminDb\n      .collection('esnaflar')\n      .where('email', '==', googleEmail)\n      .limit(1)\n      .get()\n\n    if (sorgu.empty) {\n      return NextResponse.json({ needsOnboarding: true, googleEmail, googleName })\n    }\n\n    const doc = sorgu.docs[0]\n    const esnaf = doc.data()\n\n    // Güvenlik: pasif/silindi hesaplara erişim verme\n    if (esnaf.durum === 'pasif' || esnaf.durum === 'silindi') {\n      return NextResponse.json({ needsOnboarding: true, googleEmail, googleName })\n    }\n\n    // JWT HttpOnly cookie oluştur\n    if (esnaf.durum === 'onboarding') {\n      const response = NextResponse.json({ esnafId: doc.id, durum: 'onboarding' })\n      await oturumOlustur(doc.id, response)\n      return response\n    }\n\n    const response = NextResponse.json({ esnafId: doc.id })\n    await oturumOlustur(doc.id, res